using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using AIEngineerStudio.Services;

namespace AIEngineerStudio;

public class SettingsWindow : StudioWindow
{
    readonly MainWindow owner;
    public SettingsWindow(MainWindow owner) : base(owner, "Настройки приложения", "Выберите параметры как инструменты: карточки показывают, что именно изменяет каждая настройка.")
    {
        this.owner = owner; var list = Choices(); var form = new StackPanel();
        var api = new PasswordBox { Password = owner.ApiKey, MinHeight = 36, Padding = new Thickness(8) }; api.SetResourceReference(Control.BackgroundProperty, "CardBg"); api.SetResourceReference(Control.ForegroundProperty, "Text"); api.SetResourceReference(Control.BorderBrushProperty, "Border"); var url = Field("Base URL", "Адрес OpenAI-compatible API, например https://.../v1.", owner.BaseUrl); var model = Field("Модель", "Идентификатор модели, который будет получать запросы.", owner.Model); var temp = Field("Температура", "Креативность ответа: 0 — строго, 2 — более свободно.", owner.Temperature.ToString(CultureInfo.InvariantCulture)); var max = Field("Максимум токенов", "Верхний предел длины ответа модели.", owner.MaxTokens.ToString()); var python = Field("Python", "Команда запуска Python bridge для работы с API и агентом.", owner.PythonPath);
        list.Items.Add(Card("Подключение", "Учётные данные и маршрут запроса.", form));
        Add(form, "API-токен", "Вставьте ключ провайдера, указанного в Base URL, без Bearer и кавычек. Хранится с защитой Windows DPAPI. Основная версия и WebSiteDev имеют отдельные настройки: ключ нужно сохранить в используемой версии.", api); Add(form, "Base URL", "Адрес OpenAI-compatible API, включая /v1.", url); Add(form, "Модель", "Точный идентификатор модели провайдера.", model); form.Children.Add(Action("Открыть каталог моделей", () => { var picker = new AIEngineerStudio.Views.ModelPickerWindow(model.Text) { Owner = this }; if(picker.ShowDialog() == true && picker.SelectedModel != null) model.Text = picker.SelectedModel.Id; })); Add(form, "Температура", "От 0 (точность) до 2 (креативность). Поддержка зависит от модели.", temp); Add(form, "Максимум токенов", "Лимит длины ответа. Должен соответствовать ограничениям модели.", max); Add(form, "Python", "Команда или полный путь к python.exe с установленным пакетом openai.", python);
        var theme = Choices(); theme.MaxHeight = 280;
        foreach (var item in new[] { ("Graphite (по умолчанию)", "Нейтральная тёмная палитра для работы с кодом"), ("Светлая", "Светлые поверхности и высокий контраст"), ("Midnight Blue", "Глубокие синие оттенки"), ("Emerald Night", "Тёмная тема с изумрудными акцентами") }) {
            var panel = new StackPanel(); panel.Children.Add(Text(item.Item1)); panel.Children.Add(Text(item.Item2, 11, "Muted"));
            var choice = new ListBoxItem { Content = panel, Tag = item.Item1 }; theme.Items.Add(choice); if (item.Item1 == owner.settings.Theme) theme.SelectedItem = choice;
        }
        list.Items.Add(Card("Внешний вид", "Выберите карточку темы. Палитра применяется после сохранения.", theme));
        var control = new CheckBox { Content = "Разрешить управление мышью и рабочим столом", IsChecked = owner.ComputerControlEnabled, Margin = new Thickness(0, 12, 0, 0) }; list.Items.Add(Card("Возможности агента", "Доступ к компьютеру нужен только задачам, которые требуют UI-автоматизации.", control));
        CheckBox clarification = new() { Content = "Интерактивное уточнение задач", IsChecked = owner.settings.InteractiveTaskClarification };
         CheckBox autoModel = new() { Content = "Автоматический выбор модели по сложности", IsChecked = owner.settings.AutomaticModelSelection }; var economyModel = Field("Экономичная модель", "Модель для коротких запросов и простого анализа при включённом автовыборе.", owner.settings.EconomyModel);
        list.Items.Add(Card("Общение", "Нейросеть предлагает варианты ответов для уточнения задачи и помогает составить готовый промпт для разработки", clarification));
         var performance = new StackPanel(); performance.Children.Add(autoModel); Add(performance, "Экономичная модель", "Точный ID модели из каталога API; используется только если провайдер её поддерживает.", economyModel); list.Items.Add(Card("Производительность", "Автовыбор включён по умолчанию: короткие задачи используют экономичную модель, сложные — выбранную основную.", performance));
        var prompt = new TextBox { Text = owner.PromptTemplate, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, MinHeight = 130, Padding = new Thickness(10), MaxHeight = 260, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; list.Items.Add(Card("Системный промпт", "Базовые правила поведения модели, если не выбран отдельный промпт.", prompt));
        var image = Field("", "", owner.settings.MediaImageModel); var video = Field("", "", owner.settings.MediaVideoModel);
        list.Items.Add(Card("Модель изображений", "Идентификатор генератора изображений. Каталог также доступен в разделе Медиа.", image));
        list.Items.Add(Card("Модель видео", "Идентификатор генератора видео. Пустое значение означает, что модель ещё не выбрана.", video));
        list.Items.Add(Card("Git и автокоммиты", "После задачи агента создаётся локальный коммит с описанием и списком файлов. Существующие правки требуют отдельного подтверждения до запуска. При ошибке Git файлы остаются на диске; push не выполняется.", Text("Управление репозиторием — кнопка ветвления слева вверху.", 12, "Muted")));
        Grid.SetRow(list, 1); Root.Children.Add(list); Footer.Children.Add(Action("Отмена", Close)); Footer.Children.Add(Action("Сохранить настройки", () => {
            if (!double.TryParse(temp.Text.Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out var t) || !double.IsFinite(t) || t < 0 || t > 2) { MessageBox.Show(this, "Температура должна быть числом от 0 до 2."); return; }
            if (!int.TryParse(max.Text, out var m) || m < 1) { MessageBox.Show(this, "Максимум токенов должен быть положительным целым числом."); return; }
            if (!Uri.TryCreate(url.Text.Trim(), UriKind.Absolute, out var u) || (u.Scheme != "https" && u.Scheme != "http") || string.IsNullOrWhiteSpace(model.Text) || string.IsNullOrWhiteSpace(python.Text)) { MessageBox.Show(this, "Проверьте URL, модель и путь к Python."); return; }
            var previous = System.Text.Json.JsonSerializer.Serialize(owner.settings);
            try { owner.ApiKey = api.Password.Trim(); owner.BaseUrl = url.Text.Trim(); owner.Model = model.Text.Trim(); owner.PythonPath = python.Text.Trim(); owner.ComputerControlEnabled = control.IsChecked == true; owner.settings.InteractiveTaskClarification = clarification.IsChecked == true; owner.settings.AutomaticModelSelection = autoModel.IsChecked == true; owner.settings.EconomyModel = economyModel.Text.Trim(); owner.PromptTemplate = prompt.Text; owner.Temperature = t; owner.MaxTokens = m; owner.settings.MediaImageModel = image.Text.Trim(); owner.settings.MediaVideoModel = video.Text.Trim(); owner.SetTheme((theme.SelectedItem as ListBoxItem)?.Tag?.ToString() ?? owner.settings.Theme); owner.SaveSettings(); Close(); }
            catch (Exception ex) { owner.settings = System.Text.Json.JsonSerializer.Deserialize<AppSettings>(previous)!; MessageBox.Show(this, "Не удалось сохранить настройки: " + ex.Message); }
        }, true));
    }
    static void Add(Panel p, string title, string desc, Control box) { p.Children.Add(Text(title, 12)); p.Children.Add(Text(desc, 11, "Muted")); box.Margin = new Thickness(0, 3, 0, 10); p.Children.Add(box); }
    static TextBox Field(string title, string desc, string value, bool password = false) => new() { Text = value, MinHeight = 34, ToolTip = desc };
}

public class GitWindow : StudioWindow
{
    readonly MainWindow owner; readonly ListBox files; readonly TextBox diff; readonly TextBox message; readonly TextBlock status; bool busy; int diffRequest;
    public GitWindow(MainWindow owner) : base(owner, "Git проекта", "Локальная история проекта: изменения, diff и безопасные коммиты без командной строки.")
    {
        this.owner = owner; var grid = new Grid(); grid.ColumnDefinitions.Add(new() { Width = new GridLength(300) }); grid.ColumnDefinitions.Add(new());
        files = Choices(); files.DisplayMemberPath = "Label"; files.SelectionChanged += async (_, _) => { if (files.SelectedItem is GitChange c) await LoadDiff(c); }; Grid.SetColumn(files, 0); grid.Children.Add(files);
        var right = new Grid { Margin = new Thickness(16, 0, 0, 0) }; right.RowDefinitions.Add(new() { Height = new GridLength(1, GridUnitType.Star) }); right.RowDefinitions.Add(new() { Height = GridLength.Auto }); diff = new TextBox { IsReadOnly = true, AcceptsReturn = true, TextWrapping = TextWrapping.NoWrap, FontFamily = new FontFamily("Consolas"), Padding = new Thickness(12), VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto }; diff.SetResourceReference(BackgroundProperty, "CardBg"); diff.SetResourceReference(ForegroundProperty, "Body"); right.Children.Add(diff);
        var commit = new StackPanel(); status = Text("Проверка репозитория…", 11, "Muted"); commit.Children.Add(status); message = new TextBox { Text = "Изменения проекта через AI Engineer Studio", MinHeight = 36, Margin = new Thickness(0, 8, 0, 0) }; commit.Children.Add(message); var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right }; buttons.Children.Add(Action("Обновить", async () => await Refresh())); buttons.Children.Add(Action("Создать коммит", Commit, true)); commit.Children.Add(buttons); Grid.SetRow(commit, 1); right.Children.Add(commit); Grid.SetColumn(right, 1); grid.Children.Add(right); Grid.SetRow(grid, 1); Root.Children.Add(grid); Footer.Children.Add(Action("История", async () => { try { diff.Text = await GitVersionService.RunAsync(owner.ProjectDirectory, "log", "-40", "--date=short", "--pretty=format:%h  %ad  %s", "--stat"); } catch(Exception ex) { status.Text = ex.Message; } })); Footer.Children.Add(Action("Закрыть", Close)); Loaded += async (_, _) => await Refresh();
    }
    async Task Refresh() { if(busy) return; busy = true; try { if (!await GitVersionService.IsRepositoryAsync(owner.ProjectDirectory)) { if (MessageBox.Show(this, "Создать Git-репозиторий в папке проекта?", "Git", MessageBoxButton.YesNo) != MessageBoxResult.Yes) { status.Text = "Git не инициализирован."; return; } await GitVersionService.InitializeAsync(owner.ProjectDirectory); } var changes = await GitVersionService.StatusAsync(owner.ProjectDirectory); files.ItemsSource = changes; status.Text = (await GitVersionService.RunAsync(owner.ProjectDirectory, "branch", "--show-current")).Trim() + " · " + (changes.Count == 0 ? "Рабочая папка чистая" : $"Изменений: {changes.Count}"); if (changes.Count == 0) diff.Text = "Нет незакоммиченных изменений."; } catch (Exception ex) { status.Text = "Git: " + ex.Message; } finally { busy = false; } }
    async Task LoadDiff(GitChange c) { try { var request = ++diffRequest; var result = await GitVersionService.DiffAsync(owner.ProjectDirectory, c); if(request == diffRequest) diff.Text = result; } catch (Exception ex) { diff.Text = ex.Message; } }
    async void Commit() { if(busy) return; busy = true; try { if (MessageBox.Show(this, "Включить все показанные изменения в коммит? Проверьте список на наличие секретов.", "Git", MessageBoxButton.YesNo) != MessageBoxResult.Yes) return; Root.IsEnabled = false; status.Text = "Создание коммита…"; status.Text = await GitVersionService.CommitAsync(owner.ProjectDirectory, message.Text); busy = false; await Refresh(); } catch (Exception ex) { status.Text = "Ошибка: " + ex.Message; } finally { busy = false; Root.IsEnabled = true; } }
}

public class PromptsWindow:Window { readonly MainWindow owner; readonly ListBox list; readonly TextBox name,editor; public PromptsWindow(MainWindow o){owner=o;Title="Библиотека системных промптов";Width=820;Height=560;Background=(Brush)o.FindResource("PanelBg");var grid=new Grid{Margin=new Thickness(20)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(250)});grid.ColumnDefinitions.Add(new ColumnDefinition());var left=new DockPanel();list=new ListBox{ItemsSource=o.settings.Prompts,DisplayMemberPath="Name",Background=(Brush)o.FindResource("SubBg"),Foreground=(Brush)o.FindResource("Body")};list.SelectionChanged+=(s,e)=>LoadSelected();DockPanel.SetDock(list,Dock.Top);left.Children.Add(list);var buttons=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,10,0,0)};var add=new Button{Content="＋ Создать",Margin=new Thickness(0,0,6,0)};add.Click+=(s,e)=>{var p=new SystemPrompt{Name="Новый промпт",Content=""};owner.settings.Prompts.Add(p);list.Items.Refresh();list.SelectedItem=p;};var del=new Button{Content="Удалить"};del.Click+=(s,e)=>{if(list.SelectedItem is SystemPrompt p){owner.settings.Prompts.Remove(p);owner.SaveSettings();list.Items.Refresh();}};buttons.Children.Add(add);buttons.Children.Add(del);DockPanel.SetDock(buttons,Dock.Bottom);left.Children.Add(buttons);grid.Children.Add(left);var right=new Grid{Margin=new Thickness(18,0,0,0)};right.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});right.RowDefinitions.Add(new RowDefinition());right.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});name=new TextBox{MinHeight=32,Margin=new Thickness(0,0,0,10)};right.Children.Add(name);editor=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(editor,1);right.Children.Add(editor);var save=new Button{Content="Сохранить промпт",Style=(Style)o.FindResource("AccentButton"),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};save.Click+=(s,e)=>{if(list.SelectedItem is SystemPrompt p){p.Name=name.Text.Trim();p.Content=editor.Text;owner.SaveSettings();list.Items.Refresh();}};Grid.SetRow(save,2);right.Children.Add(save);Grid.SetColumn(right,1);grid.Children.Add(right);Content=grid;list.SelectedIndex=0;}
 void LoadSelected(){if(list.SelectedItem is SystemPrompt p){name.Text=p.Name;editor.Text=p.Content;}}
}
